def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = LRUCache(maxsize=maxsize, typed=typed)
        cache_get = cache.get
        cache_del = cache.delete
        cache_clear = cache.clear

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            try:
                value, created_at = cache_get(key)
                if timer() - created_at < ttl:
                    return value
                else:
                    cache_del(key)
            except KeyError:
                pass
            value = func(*args, **kwargs)
            cache[key] = (value, timer())
            return value

        def cache_info():
            return CacheInfo(cache.hits, cache.misses, cache.maxsize, cache.currsize)

        def cache_clear():
            cache.clear()

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator

