def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    if not orderings:
        return []

    # Create a set of all elements in all orderings
    all_elements = set()
    for ordering in orderings:
        all_elements.update(ordering)

    # Create a dictionary to store the order of each element
    order_dict = {}
    for ordering in orderings:
        for index, element in enumerate(ordering):
            if element not in order_dict:
                order_dict[element] = []
            order_dict[element].append(index)

    # Sort elements by their first occurrence in any ordering
    sorted_elements = sorted(all_elements, key=lambda x: min(order_dict[x]))

    # Merge the orderings while preserving the within-ordering order
    merged_ordering = []
    used_elements = set()
    for element in sorted_elements:
        if element not in used_elements:
            for ordering in orderings:
                if element in ordering:
                    for e in ordering[ordering.index(element):]:
                        if e not in used_elements:
                            merged_ordering.append(e)
                            used_elements.add(e)

    return merged_ordering

