def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for expr in args:
        if isinstance(expr, And):
            if expr.left == expr.right.left or expr.left == expr.right.right:
                new_args.append(expr.left)
            elif expr.right.left == Not(expr.left) or expr.right.right == Not(expr.left):
                new_args.append(And(expr.left, expr.right.right if expr.right.left == Not(expr.left) else expr.right.left))
        elif isinstance(expr, Or):
            if expr.left == expr.right.left or expr.left == expr.right.right:
                new_args.append(expr.left)
            elif expr.right.left == Not(expr.left) or expr.right.right == Not(expr.left):
                new_args.append(Or(expr.left, expr.right.right if expr.right.left == Not(expr.left) else expr.right.left))
        else:
            new_args.append(expr)
    return new_args

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys

    if sys.version_info[0] < 3:
        def wrapper(*args, **kwargs):
            result = namefunc(*args, **kwargs)
            if isinstance(result, unicode):
                return result.encode('utf-8')
            return result
        return wrapper
    else:
        return namefunc

