def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0

    if platform == 1:  # POSIX
        return re.split(r'\s+', s)
    elif platform == 0:  # Windows/CMD
        return re.split(r'(?<!\\) ', s)
    else:
        raise ValueError("Unsupported platform value. Use 'this', 1 (POSIX), or 0 (Windows/CMD).")

import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if verbose:
        print(f"Running command: {commands} with args: {args}")

    try:
        result = subprocess.run(
            [commands] + args,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            check=True,
            stderr=subprocess.STDOUT if hide_stderr else None
        )
        if verbose:
            print(f"Command output: {result.stdout}")
        return result.stdout
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with error: {e.stderr}")
        raise RuntimeError(f"Command failed with error: {e.stderr}")

import ipaddress

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    try:
        ipaddress.IPv4Address(target)
        return True
    except ipaddress.AddressValueError:
        return False

