def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, (list, tuple, set)):
        return seq, type(seq)
    elif isinstance(seq, str):
        return list(seq), list
    else:
        raise TypeError("Unsupported sequence type")

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        metaclasses.add(base.__class__)

    if len(metaclasses) == 1:
        return metaclasses.pop()

    # If there are multiple metaclasses, find a common metaclass
    common_mc = None
    for mc in metaclasses:
        if common_mc is None:
            common_mc = mc
        else:
            if issubclass(mc, common_mc):
                common_mc = mc
            elif issubclass(common_mc, mc):
                continue
            else:
                raise TypeError("Inconsistent metaclasses for bases: {}".format(metaclasses))

    return common_mc

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

