import requests
from typing import Optional

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        response = requests.head(url, allow_redirects=True)
        response.raise_for_status()
        return response.headers.get('Content-Type')
    except requests.RequestException as e:
        print(f"Error fetching content type for {url}: {e}")
        return None

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        if child.tag not in result:
            result[child.tag] = []
        result[child.tag].append(child)
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if document_path is None:
        document_path = "/.well-known/nodeinfo"

    nodeinfo = {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": f"{url}{document_path}/2.0.json"
            },
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.1",
                "href": f"{url}{document_path}/2.1.json"
            }
        ]
    }

    return nodeinfo

import json
from typing import Dict, Any
from xml.etree import ElementTree as ET

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try to parse as JSON
        data = json.loads(document)
        return data
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XRD XML
        root = ET.fromstring(document)
        if root.tag != '{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD':
            raise ValueError("Invalid XRD format")

        webfinger_data = {}
        for link in root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
            rel = link.get('rel')
            href = link.get('href')
            if rel and href:
                if rel not in webfinger_data:
                    webfinger_data[rel] = []
                webfinger_data[rel].append(href)

        return webfinger_data

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        # Assuming we are using the requests library to make HTTP requests
        import requests
        response = requests.get(f"https://{handle}/.well-known/webfinger", params={"resource": handle})
        if response.status_code == 200:
            return response.text
        else:
            return None
    except Exception:
        return None

